import UIKit
import WebKit
import CoreBluetooth
@main class AppDelegate: UIResponder, UIApplicationDelegate {
 var window: UIWindow?
 func application(_ application:UIApplication,didFinishLaunchingWithOptions options:[UIApplication.LaunchOptionsKey:Any]?)->Bool {window=UIWindow(frame:UIScreen.main.bounds);window?.rootViewController=GameController();window?.makeKeyAndVisible();UIApplication.shared.isIdleTimerDisabled=true;return true}
 func applicationWillResignActive(_ application:UIApplication){(window?.rootViewController as? GameController)?.emit("window.dispatchEvent(new Event('pagehide'))");application.isIdleTimerDisabled=false}
 func applicationDidBecomeActive(_ application:UIApplication){application.isIdleTimerDisabled=true}
 func application(_ application:UIApplication,supportedInterfaceOrientationsFor window:UIWindow?)->UIInterfaceOrientationMask {.landscape}
}
class GameController:UIViewController,WKScriptMessageHandler,WKNavigationDelegate {
 var web:WKWebView!;var link:BLELink!
 override func viewDidLoad(){super.viewDidLoad();let config=WKWebViewConfiguration();config.userContentController.add(self,name:"ThienMenh");web=WKWebView(frame:view.bounds,configuration:config);web.autoresizingMask=[.flexibleWidth,.flexibleHeight];web.navigationDelegate=self;web.scrollView.isScrollEnabled=false;view.addSubview(web);link=BLELink(self);if let url=Bundle.main.url(forResource:"Thien-Menh",withExtension:"html"){web.loadFileURL(url,allowingReadAccessTo:url.deletingLastPathComponent())}}
 override var prefersStatusBarHidden:Bool {true}
 func userContentController(_ controller:WKUserContentController,didReceive message:WKScriptMessage){guard let obj=message.body as? [String:Any],let action=obj["action"] as? String else{return};let text=obj["payload"] as? String ?? "";switch action{case "host":link.host();case "scan":link.scan();case "send":link.send(text);case "disconnect":link.close();case "export":let file=FileManager.default.temporaryDirectory.appendingPathComponent("Thien-Menh-save.json");do{try Data(text.utf8).write(to:file);let share=UIActivityViewController(activityItems:[file],applicationActivities:nil);share.popoverPresentationController?.sourceView=view;present(share,animated:true)}catch{link.status("error","Could not export the save.")};default:break}}
 func webView(_ webView:WKWebView,decidePolicyFor action:WKNavigationAction,decisionHandler:@escaping(WKNavigationActionPolicy)->Void){decisionHandler(action.request.url?.isFileURL == true ? .allow:.cancel)}
 override func viewWillDisappear(_ animated:Bool){super.viewWillDisappear(animated);emit("window.dispatchEvent(new Event('pagehide'))")}
 func emit(_ js:String){DispatchQueue.main.async{self.web.evaluateJavaScript(js,completionHandler:nil)}}
}
func jsQuote(_ s:String)->String {let data=try! JSONSerialization.data(withJSONObject:[s]);let t=String(data:data,encoding:.utf8)!;return String(t.dropFirst().dropLast())}
class BLELink:NSObject,CBCentralManagerDelegate,CBPeripheralDelegate,CBPeripheralManagerDelegate {
 let service=CBUUID(string:"2F4B1200-7C8A-4F12-8B25-746D00000012"),txID=CBUUID(string:"2F4B1201-7C8A-4F12-8B25-746D00000012"),rxID=CBUUID(string:"2F4B1202-7C8A-4F12-8B25-746D00000012")
 weak var controller:GameController?;var central:CBCentralManager!;var manager:CBPeripheralManager!;var peripheral:CBPeripheral?;var tx:CBMutableCharacteristic?;var rx:CBCharacteristic?;var hosting=false;var pending:String?;var serial=0;var peers:[UUID:CBCentral]=[:];var incoming:[String:[String?]]=[:];var packets:[(CBCentral?,Data)]=[];var waiting=false;var found:Set<UUID>=[]
 init(_ c:GameController){controller=c;super.init()}
 func status(_ state:String,_ text:String){controller?.emit("window.ThienMenhLink&&ThienMenhLink.status(\(jsQuote(state)),\(jsQuote(text)))")}
 func ready(_ action:String)->Bool {if action=="host" && manager==nil{pending=action;manager=CBPeripheralManager(delegate:self,queue:.main);return false};if action != "host" && central==nil{pending=action;central=CBCentralManager(delegate:self,queue:.main);return false};let state=action=="host" ? manager.state:central.state;if state == .poweredOn{return true};if state == .unknown || state == .resetting {pending=action}else{status("error","Enable Bluetooth and allow Heavenly Mandate to use it in Settings.")};return false}
 func host(){guard ready("host") else{return};close();hosting=true;let notify=CBMutableCharacteristic(type:txID,properties:[.notify],value:nil,permissions:[]);let write=CBMutableCharacteristic(type:rxID,properties:[.write],value:nil,permissions:[.writeable]);tx=notify;let s=CBMutableService(type:service,primary:true);s.characteristics=[notify,write];manager.add(s)}
 func scan(){guard ready("scan") else{return};close();hosting=false;found=[];central.scanForPeripherals(withServices:[service],options:nil);status("scanning","Searching for a nearby host…");DispatchQueue.main.asyncAfter(deadline:.now()+20){self.central.stopScan()}}
 func centralManagerDidUpdateState(_ central:CBCentralManager){if central.state == .poweredOn,pending=="scan"{pending=nil;scan()}}
 func peripheralManagerDidUpdateState(_ peripheral:CBPeripheralManager){if peripheral.state == .poweredOn,pending=="host"{pending=nil;host()}}
 func peripheralManager(_ peripheral:CBPeripheralManager,didAdd service:CBService,error:Error?){if error != nil{status("error","Could not create a Bluetooth room.");return};manager.startAdvertising([CBAdvertisementDataServiceUUIDsKey:[self.service],CBAdvertisementDataLocalNameKey:"ThienMenh"]);status("hosting","Bluetooth room is open. Share the room PIN with your friends.")}
 func centralManager(_ central:CBCentralManager,didDiscover p:CBPeripheral,advertisementData:[String:Any],rssi RSSI:NSNumber){guard !found.contains(p.identifier) else{return};found.insert(p.identifier);let alert=UIAlertController(title:"Heavenly Mandate Host",message:p.name ?? "Bluetooth LE",preferredStyle:.alert);alert.addAction(UIAlertAction(title:"Connect",style:.default){_ in central.stopScan();self.peripheral=p;p.delegate=self;central.connect(p,options:nil)});alert.addAction(UIAlertAction(title:"Skip",style:.cancel));if controller?.presentedViewController == nil{controller?.present(alert,animated:true)}}
 func centralManager(_ central:CBCentralManager,didConnect p:CBPeripheral){p.discoverServices([service])}
 func centralManager(_ central:CBCentralManager,didFailToConnect p:CBPeripheral,error:Error?){status("error","Could not connect to the host.")}
 func centralManager(_ central:CBCentralManager,didDisconnectPeripheral p:CBPeripheral,error:Error?){waiting=false;status("disconnected","Disconnected. Move closer to the host and reconnect before trading.")}
 func peripheral(_ p:CBPeripheral,didDiscoverServices error:Error?){for s in p.services ?? [] where s.uuid==service{p.discoverCharacteristics([txID,rxID],for:s)}}
 func peripheral(_ p:CBPeripheral,didDiscoverCharacteristicsFor service:CBService,error:Error?){for c in service.characteristics ?? []{if c.uuid==rxID{rx=c};if c.uuid==txID{p.setNotifyValue(true,for:c)}}}
 func peripheral(_ p:CBPeripheral,didUpdateNotificationStateFor c:CBCharacteristic,error:Error?){if error == nil && c.isNotifying{status("connected","Bluetooth LE connected.")}else{status("error","Could not open the Bluetooth receive channel.")}}
 func peripheral(_ p:CBPeripheral,didUpdateValueFor c:CBCharacteristic,error:Error?){if let data=c.value,let text=String(data:data,encoding:.utf8){receive("host",text)}}
 func peripheral(_ p:CBPeripheral,didWriteValueFor c:CBCharacteristic,error:Error?){waiting=false;if error != nil{status("error","A Bluetooth packet was interrupted.")};flush()}
 func peripheralManager(_ manager:CBPeripheralManager,central:CBCentral,didSubscribeTo characteristic:CBCharacteristic){peers[central.identifier]=central}
 func peripheralManager(_ manager:CBPeripheralManager,central:CBCentral,didUnsubscribeFrom characteristic:CBCharacteristic){peers.removeValue(forKey:central.identifier);controller?.emit("window.ThienMenhLink&&ThienMenhLink.peerLeft(\(jsQuote(central.identifier.uuidString)))");status("peer-left","A device disconnected.")}
 func peripheralManager(_ manager:CBPeripheralManager,didReceiveWrite requests:[CBATTRequest]){for r in requests {guard r.characteristic.uuid==rxID,let data=r.value,let text=String(data:data,encoding:.utf8) else{manager.respond(to:r,withResult:.invalidAttributeValueLength);continue};manager.respond(to:r,withResult:.success);receive(r.central.identifier.uuidString,text)}}
 func peripheralManagerIsReady(toUpdateSubscribers peripheral:CBPeripheralManager){flush()}
 func receive(_ from:String,_ packet:String){let p=packet.split(separator:":",maxSplits:3,omittingEmptySubsequences:false).map(String.init);guard p.count==4,let i=Int(p[1],radix:16),let n=Int(p[2],radix:16),n>0,n<=65535,i>=0,i<n else{return};let key=from+":"+p[0];if incoming.count>16{incoming.removeAll()};var parts=incoming[key] ?? [String?](repeating:nil,count:n);guard parts.count==n else{return};parts[i]=p[3];incoming[key]=parts;if parts.allSatisfy({$0 != nil}){let wire=parts.compactMap{$0}.joined();incoming.removeValue(forKey:key);guard wire.utf8.count<=5000000 else{return};controller?.emit("window.ThienMenhLink&&ThienMenhLink.message(\(jsQuote(from)),\(jsQuote(wire)))")}}
 func send(_ text:String){guard text.utf8.count<=5000000 else{return};if hosting{for peer in peers.values{frame(text,peer,max:peer.maximumUpdateValueLength)}}else if let p=peripheral,rx != nil{frame(text,nil,max:p.maximumWriteValueLength(for:.withResponse))};flush()}
 func frame(_ text:String,_ peer:CBCentral?,max:Int){let data=Array(text.utf8),size=Swift.max(1,Swift.min(140,max-17)),total=(data.count+size-1)/size;guard total<=65535 else{return};serial=(serial+1)&0xffffff;for i in 0..<total {let head=String(format:"%06x:%04x:%04x:",serial,i,total);var part=Data(head.utf8);part.append(contentsOf:data[i*size..<Swift.min(data.count,(i+1)*size)]);packets.append((peer,part))}}
 func flush(){if hosting{guard let tx=tx else{return};while let first=packets.first {guard let peer=first.0,peers[peer.identifier] != nil else{packets.removeFirst();continue};if !manager.updateValue(first.1,for:tx,onSubscribedCentrals:[peer]){return};packets.removeFirst()}}else{guard !waiting,let p=peripheral,let rx=rx,!packets.isEmpty else{return};let first=packets.removeFirst();waiting=true;p.writeValue(first.1,for:rx,type:.withResponse)}}
 func close(){central?.stopScan();if let p=peripheral{central?.cancelPeripheralConnection(p)};manager?.stopAdvertising();manager?.removeAllServices();peripheral=nil;rx=nil;tx=nil;peers.removeAll();packets.removeAll();incoming.removeAll();waiting=false}
}
